-- Create passive payroll record history snapshots captured by Save All.

begin;

create table if not exists public."Record History" (
    "Id" integer generated by default as identity,
    "PayrollRecordId" integer not null,
    "Employee #" character varying(50) not null,
    "Employees Name" character varying(200) not null,
    "RP#" character varying(50) not null,
    "Employer Name" character varying(200) not null,
    "Employer Group" character varying(100) not null,
    "Employer Address" character varying(300) not null,
    "Employer City" character varying(100) not null,
    "Employer Postal code" character varying(20) not null,
    "Employee Address" character varying(300) not null,
    "Employee City" character varying(100) not null,
    "Employee Province" character varying(50) not null,
    "Employee Postal Code" character varying(20) not null,
    "Employee E-Mail Address" character varying(200) not null,
    "Period" integer not null,
    "Period Beginning" date not null,
    "Period Ending" date not null,
    "Pay Date" date not null,
    "Month" integer not null,
    "Year" integer not null,
    "Saved At" timestamp with time zone not null,
    "Salary" numeric(18,2) not null,
    "Rate" numeric(18,2) not null,
    "R.Hours" numeric(18,2) not null,
    "OV.Hours" numeric(18,2) not null,
    "Public.H" numeric(18,2) not null,
    "S.H Hours" numeric(18,2) not null,
    "Vacation" numeric(18,2) not null,
    "Vacation Used" numeric(18,2) not null,
    "vacation_setting" character varying(20) not null,
    "Gross" numeric(18,2) not null,
    "Paid Vacation" numeric(18,2) not null,
    "Total Pay" numeric(18,2) not null,
    "TAX1" numeric(18,2) not null,
    "CPP1" numeric(18,2) not null,
    "CPP2" numeric(18,2) not null,
    "EI" numeric(18,2) not null,
    "Other deduction" numeric(18,2) not null,
    "Total Deductions" numeric(18,2) not null,
    "NET PAY" numeric(18,2) not null,
    "Gross-YTD" numeric(18,2) not null,
    "NET-YTD" numeric(18,2) not null,
    "TAX -YTD" numeric(18,2) not null,
    "CPP1-YTD" numeric(18,2) not null,
    "CPP2-YTD" numeric(18,2) not null,
    "EI-YTD" numeric(18,2) not null,
    "Other Deduction-YTD" numeric(18,2) not null,
    "Vacation -YTD" numeric(18,2) not null,
    "Vacation -YTD-Used" numeric(18,2) not null,
    "Vacation -YTD- Balance" numeric(18,2) not null,
    "Total Pay-YTD" numeric(18,2) not null,
    "Total Deductions-YTD" numeric(18,2) not null,
    "Total PD7" numeric(18,2) not null,
    constraint "PK_Record History" primary key ("Id")
);

create index if not exists "IX_Record History_Employee #"
    on public."Record History" ("Employee #");

create index if not exists "IX_Record History_RP#"
    on public."Record History" ("RP#");

create index if not exists "IX_Record History_Year_Month"
    on public."Record History" ("Year", "Month");

commit;
